head.script:
//
(function () {
  try {
    var t = localStorage.getItem('tema');
    if (t) document.documentElement.setAttribute('data-tema', t);
  } catch (e) { /* modo privado: segue o tema do sistema */ }
})();
//

head.b:skin:
/*
=============================================================================
  FOLHA DE ESTILO
  ---------------------------------------------------------------------------
  01. Temas (:root)          <- personalize tudo aqui
  01b. Tokens fixos (fontes, tamanhos, larguras)
  02. Reset e base
  03. Tipografia
  04. Estrutura / wrappers
  05. Cabecalho
  06. Menu principal (topo / barra inferior)
  06b. Menu no telemovel
  07. Posts populares (destaques)
  08. Posts
  09. Postagens relacionadas
  10. Sidebar
  11. Comentarios
  12. Paginacao
  13. Rodape
  14. Responsivo
  15. Editor Layout do Blogger
  16. Botao de tema
=============================================================================
*/

/* ------------------------------------------------------------------
   01. TEMAS
   Cada tema e apenas um conjunto de variaveis. Para criar um novo,
   copie um bloco :root[data-tema="..."], mude o nome e junte-o ao
   array TEMAS do script que fica no fim do <body>.

   Sem o atributo data-tema  -> segue a preferencia do sistema.
   Com data-tema="escuro"    -> escolha explicita do leitor, guardada
                                no localStorage do navegador dele.
   ------------------------------------------------------------------ */

/* --- Tema CLARO (predefinido) --- */
:root{
  color-scheme: light;
  --cor-fundo:        #ffffff;   /* fundo da pagina                    */
  --cor-texto:        #262626;   /* texto corrido                      */
  --cor-texto-suave:  #8c8c8c;   /* datas, autor, legendas             */
  --cor-titulo:       #111111;   /* titulos                            */
  --cor-link:         #666666;   /* links em repouso                   */
  --cor-link-hover:   #111111;   /* links sob o cursor                 */
  --cor-borda:        #ececec;   /* linhas divisorias                  */
  --cor-superficie:   #fafafa;   /* fundos leves (citacoes, botoes)    */
  --cor-contraste:    #ffffff;   /* texto sobre fundo escuro           */
  --cor-veu:          rgba(255,255,255,.88);  /* overlay dos destaques */
}

/* --- Tema ESCURO --- */
:root[data-tema="escuro"]{
  color-scheme: dark;
  --cor-fundo:        #121212;
  --cor-texto:        #d8d8d8;
  --cor-texto-suave:  #7d7d7d;
  --cor-titulo:       #f2f2f2;
  --cor-link:         #a3a3a3;
  --cor-link-hover:   #ffffff;
  --cor-borda:        #2b2b2b;
  --cor-superficie:   #1c1c1c;
  --cor-contraste:    #121212;
  --cor-veu:          rgba(18,18,18,.88);
}

/* --- Modo automatico: aplica o escuro se o sistema pedir escuro
       e o leitor ainda nao tiver escolhido nada. --- */
@media (prefers-color-scheme: dark){
  :root:not([data-tema]){
    color-scheme: dark;
    --cor-fundo:        #121212;
    --cor-texto:        #d8d8d8;
    --cor-texto-suave:  #7d7d7d;
    --cor-titulo:       #f2f2f2;
    --cor-link:         #a3a3a3;
    --cor-link-hover:   #ffffff;
    --cor-borda:        #2b2b2b;
    --cor-superficie:   #1c1c1c;
    --cor-contraste:    #121212;
    --cor-veu:          rgba(18,18,18,.88);
  }
}

/* --- Tema SEPIA (exemplo de terceiro tema) --- */
:root[data-tema="sepia"]{
  color-scheme: light;
  --cor-fundo:        #f4ecd8;
  --cor-texto:        #3b2f22;
  --cor-texto-suave:  #8a7a63;
  --cor-titulo:       #2a2019;
  --cor-link:         #6b5942;
  --cor-link-hover:   #2a2019;
  --cor-borda:        #ddd0b6;
  --cor-superficie:   #ebe0c8;
  --cor-contraste:    #f4ecd8;
  --cor-veu:          rgba(244,236,216,.88);
}

/* --- Tema TERMINAL (exemplo: verde sobre preto) --- */
:root[data-tema="terminal"]{
  color-scheme: dark;
  --cor-fundo:        #0b0f0b;
  --cor-texto:        #9ae69a;
  --cor-texto-suave:  #4f7a4f;
  --cor-titulo:       #c8ffc8;
  --cor-link:         #6fbf6f;
  --cor-link-hover:   #c8ffc8;
  --cor-borda:        #1d2a1d;
  --cor-superficie:   #101710;
  --cor-contraste:    #0b0f0b;
  --cor-veu:          rgba(11,15,11,.88);
}

/* --- Tema RISO: rosa, azul ultramar e vermelho ---
       Tres tintas tiradas de um poster de risografia. Os tons foram
       escurecidos o suficiente para o texto cumprir o contraste
       minimo AA (4.5:1): o vermelho original ficava em 3.7:1. --- */
:root[data-tema="riso"]{
  color-scheme: light;
  --cor-fundo:        #ffdcd4;   /* rosa do papel              */
  --cor-texto:        #2b2f5c;   /* azul ultramar escuro       */
  --cor-texto-suave:  #68607a;
  --cor-titulo:       #1d2147;
  --cor-link:         #3f5bb5;   /* azul de impressao          */
  --cor-link-hover:   #b3280f;   /* vermelho da terceira tinta */
  --cor-borda:        #f0bcb2;
  --cor-superficie:   #ffe9e4;
  --cor-contraste:    #ffdcd4;
  --cor-veu:          rgba(255,220,212,.9);
}

/* --- Tema AZULEJO: azul, vermelho e bege ---
       Bege claro tipo pedra de Lisboa, azul de azulejo e vermelho
       terracota. Contrastes conferidos para AA (4.5:1); o
       texto-suave original (#7a6a52) ficava em 4.23:1 e foi
       escurecido para #6f6048 (4.92:1). --- */
:root[data-tema="azulejo"]{
  color-scheme: light;
  --cor-fundo:        #f0e6d2;   /* bege/creme               */
  --cor-texto:        #1c2f45;   /* azul-marinho             */
  --cor-texto-suave:  #6f6048;
  --cor-titulo:       #14232f;
  --cor-link:         #2f5f86;   /* azul de azulejo          */
  --cor-link-hover:   #a8331f;   /* vermelho terracota       */
  --cor-borda:        #ddd0ae;
  --cor-superficie:   #e8dcc2;
  --cor-contraste:    #f0e6d2;
  --cor-veu:          rgba(240,230,210,.9);
}

/* ------------------------------------------------------------------
   01b. TOKENS QUE NAO MUDAM COM O TEMA
   Fontes, tamanhos e larguras ficam aqui, definidos uma unica vez.
   ------------------------------------------------------------------ */
:root{
  /* -- Tipografia -- */
  --fonte-base:   "Inconsolata", monospace;
  --fonte-auxiliar: "Victor Mono", monospace;
  --fonte-auxiliar2: "Aboreto", sans-serif;
  --fonte-titulo: var(--fonte-base);
  --texto-xs:     11px;   /* metadados, rodape do post */
  --texto-sm:     13px;   /* sidebar, comentarios       */
  --texto-base:   15px;   /* corpo do post              */
  --titulo-blog:  34px;
  --titulo-post:  24px;
  --altura-linha: 1.75;
  --espaco-letra: .12em;  /* usado nos textos em maiusculas */

  /* --accent: adicionado para o hover de .post-body a corrigido
     abaixo, na seccao 04. Sem esta linha, --accent nao existia em
     nenhum tema e o hover ficava sem cor (var() invalido cai no
     valor herdado, ou seja, nada muda). Aponta para o mesmo tom
     usado no resto do site para hover de link. */
  --accent: var(--cor-link-hover);

  /* -- Layout -- */
  --largura-site:    1040px;  /* largura maxima do conteudo   */
  --largura-sidebar: 230px;
  --largura-leitura: 760px;   /* largura sem sidebar          */
  --gap:             44px;    /* espaco entre post e sidebar  */
  --espaco:          24px;    /* unidade base de respiro      */
  --transicao:       .2s ease;
}

/* ------------------------------------------------------------------
   02. RESET E BASE
   ------------------------------------------------------------------ */
*, *::before, *::after{ box-sizing:border-box; }
*{ margin:0; padding:0; list-style:none; }

body{
  background:var(--cor-fundo);
  color:var(--cor-texto);
  font-family:var(--fonte-base);
  font-size:var(--texto-base);
  line-height:var(--altura-linha);
  overflow-x:hidden;
}
/* Suaviza a troca de tema sem animar tudo (animar a pagina inteira
   causa engasgos em listas longas). */
body{ transition:background-color .25s ease, color .25s ease; }

img{ max-width:100%; height:auto; border:0; }
.clear{ clear:both; }

i{font-family: var(--fonte-auxiliar);}

a{color:var(--cor-link); text-decoration:none; transition:color var(--transicao); }
a:visited{ color:var(--cor-link); }
a:hover{ color:var(--cor-link-hover); }
/* ------------------------------------------------------------------
   03. TIPOGRAFIA
   h1 = titulo do blog | h2 = titulos de widgets | h3 = titulo do post
   ------------------------------------------------------------------ */
h1, h2, h3, h4{
  font-family:var(--fonte-titulo);
  font-weight:400;
  color:var(--cor-titulo);
  margin:0 0 10px;
  line-height:1.3;
}
h1{ font-size:var(--titulo-blog); font-weight:300; letter-spacing:.04em; text-align:center; }
h2{
  font-size:var(--texto-xs);
  font-weight:600;
  letter-spacing:var(--espaco-letra);
  text-transform:uppercase;
}
h3{ font-size:var(--titulo-post); font-weight:400; }
h4{ font-size:var(--texto-sm); font-weight:600; }

/* Classe utilitaria: textos pequenos em maiusculas (metadados) */
.date-header, .fn, .comment-link, .post-footer, #blog-pager, .creditos{
  font-size:var(--texto-xs);
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  color:var(--cor-texto-suave);
}

/* ------------------------------------------------------------------
   04. ESTRUTURA / WRAPPERS
   Sem floats: o conteudo usa flexbox, o que dispensa hacks de largura.
   ------------------------------------------------------------------ */
#outer-wrapper{
  width:100%;
  max-width:var(--largura-site);
  margin:0 auto 80px;
  padding:0 20px;
}
#crosscol-wrapper{ width:100%; margin:0 auto 50px; }

#content-wrapper{
  display:flex;
  align-items:flex-start;
  gap:var(--gap);
}
#main-wrapper{ flex:1 1 auto; min-width:0; word-wrap:break-word; }
#sidebar-wrapper{ flex:0 0 var(--largura-sidebar); width:var(--largura-sidebar); word-wrap:break-word; }

/* Paginas sem sidebar (home, marcadores, arquivo, paginas estaticas):
   o conteudo ocupa toda a largura, mas com um limite de leitura
   confortavel e centrado. Ajuste em --largura-leitura. */
#content-wrapper.sem-sidebar #main-wrapper{
  max-width:var(--largura-leitura);
  margin:0 auto;
}

/* A sidebar so aparece na pagina de um post. Escondida por CSS e nao
   por <b:if>, para continuar visivel e editavel no painel Layout. */
#content-wrapper.sem-sidebar #sidebar-wrapper{ display:none; }

/* --- HOMEPAGE ---
   Na primeira pagina mostra-se a apresentacao e escondem-se os posts;
   nas restantes paginas e ao contrario. Feito por CSS (e nao por
   <b:if>) para as duas seccoes continuarem editaveis no painel Layout. */
#home-wrapper{ display:none; }
#content-wrapper.pagina-home #home-wrapper{ display:block; }
#content-wrapper.pagina-home #main .Blog,
#content-wrapper.pagina-home #blog-pager,
#content-wrapper.pagina-home .feed-links{ display:none; }

/* A mesa precisa de toda a largura, sem o limite de leitura. */
#content-wrapper.pagina-home #main-wrapper{ max-width:none; }

/* --- PAGINAS DE LISTA (marcador, pesquisa, arquivo) ---
   Cada post vira um cartao com titulo e data. O Blogger envolve os
   posts em .date-outer > .date-posts; display:contents tira essas
   caixas do fluxo para os cartoes serem filhos diretos da grelha. */
#content-wrapper.pagina-lista #main-wrapper{ max-width:none; }

.pagina-lista .blog-posts{
  display:grid;
  grid-template-columns:repeat(auto-fill, minmax(230px, 1fr));
  gap:14px;
  margin-bottom:40px;
}
.pagina-lista .date-outer,
.pagina-lista .date-posts{ display:contents; }

.pagina-lista .post-outer{ display:flex; }

.pagina-lista .post{
  position:relative;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  gap:14px;
  width:100%;
  min-height:130px;
  margin:0;
  padding:18px;
  background:var(--cor-superficie);
  border:1px solid var(--cor-borda);
  border-radius:3px;
  transition:transform var(--transicao),
             border-color var(--transicao),
             box-shadow var(--transicao);
}

/* Efeito ao passar o cursor: o cartao levanta um pouco. */
.pagina-lista .post:hover{
  transform:translateY(-3px);
  border-color:var(--cor-texto-suave);
  box-shadow:0 6px 18px rgba(0,0,0,.10);
}
.pagina-lista .post:hover .post-title a{ color:var(--cor-link-hover); }

/* Titulo */
.pagina-lista .post h3.post-title{ margin:0; }
.pagina-lista .post h3 a,
.pagina-lista .post h3 strong{
  font-size:15px;
  line-height:1.4;
  font-weight:600;
  color:var(--cor-titulo);
  transition:color var(--transicao);
}

/* O link do titulo cobre o cartao todo, para se poder clicar
   em qualquer ponto. */
.pagina-lista .post h3 a::after{
  content:'';
  position:absolute;
  inset:0;
}

/* Data: sem a linha divisoria e sem os restantes metadados. */
.pagina-lista .post-header{ order:2; }
.pagina-lista .post-header-line-1{
  gap:8px;
  padding:0;
  border:0;
}
.pagina-lista .date-header{
  font-size:10px;
  color:var(--cor-texto-suave);
}

/* Tudo o resto sai do cartao. */
.pagina-lista .post-body,
.pagina-lista .post-footer,
.pagina-lista .jump-link,
.pagina-lista .post-comment-link,
.pagina-lista .post-author,
.pagina-lista #at-gambar,
.pagina-lista .comments,
.pagina-lista .status-msg-border{ display:none; }

/* Mensagem "Mostrando postagens com o marcador X".
   Como fica dentro de .blog-posts, tambem e um item da grelha:
   sem o grid-column ocuparia a primeira celula e empurrava o
   primeiro cartao para o lado. */
.pagina-lista .status-msg-wrap{
  grid-column:1 / -1;
  position:static;
  width:100%;
  margin:0 0 12px;
}
.pagina-lista .status-msg-body{
  position:static;
  padding:0;
  text-align:left;
  font-size:var(--texto-xs);
  letter-spacing:var(--espaco-letra);
  text-transform:uppercase;
  color:var(--cor-texto-suave);
}

@media screen and (max-width:600px){
  .pagina-lista .blog-posts{
    grid-template-columns:1fr;
    gap:10px;
  }
  .pagina-lista .post{ min-height:0; }
}

#footer-wrapper{ width:100%; }

.post-body a,
.post p a {
  color: var(--cor-texto-suave);
  text-decoration: none;
  padding-bottom: 3px;
  /*border-bottom: 1.5px dotted var(--cor-texto-suave); */
  transition: .25s ease;
}

.post-body a:hover,
.post p a:hover {
  color: var(--accent);
   /* border-bottom-color: var(--accent); */
}

/* ------------------------------------------------------------------
   05. CABECALHO
   ------------------------------------------------------------------ */
#header-inner{ margin:0 auto; background-position:center; }
#header{ text-align:center; }
#header h1{ margin:0; }
#header a{ color:var(--cor-titulo); }
#header a:hover{ color:var(--cor-texto-suave); }
#header .description{
  max-width:640px;
  margin:12px auto 0;
  font-size:var(--texto-xs);
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  color:var(--cor-texto-suave);
}
#header img{ margin:0 auto; }

/* ------------------------------------------------------------------
   06. CABECALHO + MENU  (nome do blog + widget PageList)
   Uma unica barra no topo: o nome fica a esquerda, as paginas a
   direita. O botao de tema NAO vive mais aqui -- foi para o rodape
   (seccao 13).

   Ecra grande : uma linha, nome + paginas em texto.
   Telemovel   : o nome fica no topo (sozinho); as paginas descem
                 para uma barra fixa no fundo, so com icones. Os
                 icones sao injetados pelo script no fim do <body>.

   Estrutura no HTML (ver <body>):
     #menu-wrapper
       .menu-topo
         #header-wrapper   (nome do blog, widget Header1)
         .menu-links       (envolve o widget PageList1)

   Centragem/alinhamento: o widget do Blogger envolve a lista em
   tres <div> aninhadas. Com display:contents essas caixas deixam
   de contar para o layout, e os <li> passam a ser filhos diretos
   do flex dentro de .menu-links.
   ------------------------------------------------------------------ */
#menu-wrapper{
  position:sticky;
  top:0;
  z-index:900;
  width:100%;
  background:var(--cor-fundo);
  border-bottom:1px solid var(--cor-borda);
}

.menu-topo{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
  max-width:var(--largura-site);
  margin:0 auto;
  padding:0 20px;
}

/* --- Nome do blog, agora compacto e a esquerda --- */
#header-wrapper{ padding:0; flex:0 0 auto; }
#header{ text-align:left; }
#header-inner{ margin:0; }
#header h1{
  margin:0;
  font-size:var(--texto-sm);
  font-weight:600;
  letter-spacing:var(--espaco-letra);
  text-transform:uppercase;
  text-align:left;
}
/* A descricao (subtitulo do blog) nao cabe numa barra fina;
   fica reservada para quem quiser reativa-la manualmente. */
#header .description{ display:none; }

/* --- Paginas, agora a direita --- */
.menu-links{ display:flex; align-items:stretch; min-width:0; }

.menu-links .section,
.menu-links .widget,
.menu-links .widget-content,
.menu-links #PageList1 ul{ display:contents; }
.menu-links h2{ display:none; }

#PageList1 li{ display:flex; margin:0; }

#PageList1 a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  padding:15px 14px;
  border:0;
  background:transparent;
  font-family:var(--fonte-base);
  font-size:var(--texto-xs);
  font-weight:600;
  letter-spacing:var(--espaco-letra);
  text-transform:uppercase;
  line-height:1;
  color:var(--cor-texto-suave);
  cursor:pointer;
  -webkit-appearance:none;
  appearance:none;
  transition:color var(--transicao);
}
#PageList1 a:visited{ color:var(--cor-texto-suave); }
#PageList1 a:hover{ color:var(--cor-titulo); }
#PageList1 .selected a{ color:var(--cor-titulo); }

#PageList1 a:focus-visible{
  outline:2px solid var(--cor-link-hover);
  outline-offset:-4px;
}

/* O icone herda a cor do texto e nunca encolhe. Usado tambem pelo
   botao de tema, agora no rodape (ver seccao 13/16). */
.menu-icone{
  flex:0 0 auto;
  width:21px;
  height:21px;
  stroke:currentColor;
  fill:none;
  stroke-width:1.6;
  stroke-linecap:round;
  stroke-linejoin:round;
}

/* No ecra grande: so texto nas paginas. */
#PageList1 .menu-icone{ display:none; }

/* ------------------------------------------------------------------
   06b. MENU NO TELEMOVEL
   O nome do blog fica onde esta (topo, sticky). So .menu-links vira
   uma barra fixa no fundo, com icones -- por isso o position:fixed
   vai em .menu-links e nao em #menu-wrapper: um elemento fixed
   posiciona-se em relacao ao ecra independentemente de onde vive no
   HTML (a nao ser que um antepassado tenha transform/filter, o que
   nao e o caso aqui), entao o nome continua normal no topo.
   O padding-bottom no body impede que a barra tape o fim do
   conteudo; env(safe-area-inset-bottom) trata da barra de gestos
   do iPhone.
   ------------------------------------------------------------------ */
@media screen and (max-width:700px){
  .menu-topo{ padding:0 16px; }

  #header-wrapper{ padding:14px 0; }
  #header h1{ font-size:var(--texto-xs); }

  .menu-links{
    position:fixed;
    left:0;
    right:0;
    bottom:0;
    z-index:900;
    background:var(--cor-fundo);
    border-top:1px solid var(--cor-borda);
    padding-bottom:env(safe-area-inset-bottom, 0px);
  }

  body{ padding-bottom:76px; }

  /* Cada pagina ocupa exatamente a mesma fatia da largura. */
  #PageList1 li{ flex:1 1 0; min-width:0; }
  #PageList1 a{ flex:1 1 auto; padding:15px 0; }

  /* So icones. */
  #PageList1 .menu-icone{ display:block; }
  .menu-rotulo{
    position:absolute;
    width:1px;
    height:1px;
    overflow:hidden;
    clip:rect(0 0 0 0);
    white-space:nowrap;
  }
}

/* ------------------------------------------------------------------
   07. POSTS POPULARES EM DESTAQUE (3 colunas no topo)
   O titulo aparece por cima da imagem ao passar o cursor.
   ------------------------------------------------------------------ */
.crosscol .PopularPosts ul{
  display:flex;
  flex-wrap:wrap;
  gap:2%;
}
.crosscol .PopularPosts ul li{
  position:relative;
  flex:0 0 32%;
  max-height:240px;
  margin:0 0 2%;
  overflow:hidden;
}
.crosscol .PopularPosts img{ width:100%; height:240px; object-fit:cover; display:block; }
.crosscol .PopularPosts .item-content{ position:relative; }
.crosscol .PopularPosts .item-title a{
  position:absolute;
  inset:0;                      /* mesmo que top/right/bottom/left:0 */
  display:flex;
  align-items:center;
  justify-content:center;
  padding:0 8%;
  background:var(--cor-veu);
  color:var(--cor-titulo);
  font-size:var(--texto-xs);
  font-weight:600;
  text-align:center;
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  opacity:0;
  visibility:hidden;
  transition:opacity var(--transicao);
}
.crosscol .PopularPosts .item-content:hover .item-title a,
.crosscol .PopularPosts .item-thumbnail-only:hover .item-title a{
  opacity:1;
  visibility:visible;
}
.crosscol .PopularPosts .item-snippet{ display:none; }

/* ------------------------------------------------------------------
   08. POSTS
   ------------------------------------------------------------------ */
.post{ position:relative; margin:0 auto 70px; }

/* Quickedit: o lapis que so o autor logado ve, para editar o post
   sem passar pelo painel do Blogger. O proprio Blogger controla
   quando ele aparece (a classe adminClass so existe quando o
   visitante e um autor do blog); aqui so cuidamos do aspeto, para
   nao depender do CSS de administrador que o Blogger injeta, que
   um skin totalmente customizado como este pode acabar cobrindo. */
.item-control.quickedit{
  position:absolute;
  top:0;
  right:0;
  z-index:5;
  opacity:.35;
  transition:opacity var(--transicao);
}
.post:hover .item-control.quickedit{ opacity:1; }
.item-control.quickedit a{
  display:flex;
  align-items:center;
  justify-content:center;
  width:30px;
  height:30px;
  background:var(--cor-superficie);
  border:1px solid var(--cor-borda);
  border-radius:50%;
  color:var(--cor-texto-suave);
}
.item-control.quickedit a:hover{ color:var(--cor-titulo); border-color:var(--cor-texto-suave); }
.quickedit-icone{
  width:14px;
  height:14px;
  stroke:currentColor;
  fill:none;
  stroke-width:1.8;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.post h3.post-title{ margin:0 0 12px; }
.post h3 a, .post h3 a:visited, .post h3 strong{ display:block; color:var(--cor-titulo); font-weight:400; }
.post h3 a:hover{ color:var(--cor-link); }

/* Linha de metadados: autor - data - comentarios, separados por barra */
.post-header-line-1{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:14px;
  padding-bottom:18px;
  border-bottom:1px solid var(--cor-borda);
}
.post-header-line-1 > span:empty{ display:none; }
.fn a, .comment-link, .date-header{ color:var(--cor-texto-suave); }
.fn a:hover, .comment-link:hover{ color:var(--cor-link-hover); }

.post-body{ margin:26px auto 40px; }
.post-body p{ margin:0 0 1.2em; }
.post img, table.tr-caption-container{ max-width:100%; height:auto; }
.tr-caption-container img{ border:0; padding:0; }
.tr-caption, .legend{
  margin:0 auto 24px;
  padding:8px 0;
  font-size:var(--texto-sm);
  font-style:italic;
  color:var(--cor-texto-suave);
}
.post blockquote{
  margin:28px 0;
  padding:20px 26px;
  border-left:2px solid var(--cor-titulo);
  background:var(--cor-superficie);
}
.post-body blockquote{ font-style:italic; }
.post ul, .post ol{ margin:0 0 1.2em 22px; }
.post li{ list-style:disc; margin:6px 0; }
.post ol li{ list-style:decimal; }

/* Botao "Leia mais" */
.jump-link{ margin:0 0 40px; }
.jump-link a{
  display:inline-block;
  padding:10px 22px;
  border:1px solid var(--cor-borda);
  font-size:var(--texto-xs);
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  transition:background var(--transicao), color var(--transicao);
}
.jump-link a:hover{ background:var(--cor-titulo); color:var(--cor-contraste); }

/* Rodape do post: compartilhar a esquerda, marcadores/data a direita */
.post-footer{
  display:flex;
  flex-wrap:wrap;
  justify-content:space-between;
  align-items:center;
  gap:12px;
  padding-top:16px;
  border-top:1px solid var(--cor-borda);
}
.post-footer a, .post-footer a:visited{ color:var(--cor-texto-suave); }
.post-footer a:hover{ color:var(--cor-link-hover); }
.post-footer-line-2{ text-align:right; }
.post-labels a{ margin-left:4px; }

/* Links de compartilhamento (agora em texto, sem imagens externas) */
.compartilhar{ display:inline-flex; gap:16px; }
.compartilhar a{ color:var(--cor-texto-suave); }
.compartilhar a:hover{ color:var(--cor-link-hover); }

/* Localizacao do post: icone de pin + texto. Quando o post nao tem
   localizacao propria, o script no fim do <body> preenche o texto
   com Brasilia (antes de 2021) ou Porto (2021 em diante). */
.post-location a{ display:inline-flex; align-items:center; gap:4px; }
.pin-icone{
  flex:0 0 auto;
  width:11px;
  height:11px;
  stroke:currentColor;
  fill:none;
  stroke-width:2;
  stroke-linecap:round;
  stroke-linejoin:round;
}

/* ------------------------------------------------------------------
   09. POSTAGENS RELACIONADAS  (#at-gambar)
   Depende de um script externo; veja o comentario no <head>.
   ------------------------------------------------------------------ */
#at-gambar{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin:0 0 60px;
  font-size:10px;
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  text-align:center;
}
#at-gambar h2{ display:none; }
#at-gambar a{ flex:1 1 120px; color:var(--cor-texto-suave); opacity:.85; transition:opacity var(--transicao); }
#at-gambar a:hover{ opacity:1; }
#at-gambar img{ width:100%; height:118px; object-fit:cover; }
.box-related{ line-height:1.4; }

/* ------------------------------------------------------------------
   10. SIDEBAR
   Cada gadget e um cartao com o mesmo fundo dos comentarios. Fica
   colada ao topo ao rolar (sticky), o que compensa a coluna ser
   agora mais estreita: aproveita melhor o espaco em posts longos.
   ------------------------------------------------------------------ */
.sidebar{ font-size:var(--texto-sm); }

#sidebar-wrapper{
  position:sticky;
  top:70px;              /* altura da barra de menu + folga */
  align-self:flex-start;
}

.sidebar .widget{
  margin:0 0 16px;
  padding:16px;
  border-radius:3px;
}
.sidebar .widget:last-child{ margin-bottom:0; }

/* Um gadget so com imagem nao precisa de moldura dupla. */
.sidebar .Image{ padding:0; overflow:hidden; }
.sidebar .Image .widget-content img{ margin:0; display:block; width:100%; }
.sidebar .Image h2{ margin:14px 18px 0; }

.sidebar h2{
  margin:0 0 12px;
  padding-bottom:10px;
  border-bottom:1px solid var(--cor-borda);
  text-align:left;
}
.sidebar .widget-content img{ margin:10px auto; display:block; }
.sidebar a, .sidebar a:visited{ color:var(--cor-texto); }
.sidebar a:hover{ color:var(--cor-texto-suave); }
.sidebar li{ margin:0 0 8px; padding:0; color:var(--cor-texto-suave); }
.sidebar li:last-child{ margin-bottom:0; }
.sidebar .label-size{ display:inline-block; margin:0 8px 8px 0; font-size:var(--texto-xs); }

/* ------------------------------------------------------------------
   11. COMENTARIOS
   Cada comentario e um cartao com fundo proprio. Os avatares foram
   removidos: o Blogger serve-os do Google, muitas vezes sao a
   silhueta cinzenta por omissao, e sem eles a coluna fica alinhada.
   ------------------------------------------------------------------ */
.comments{ width:100%; margin:40px auto 0; }
.comments h4{
  margin:0 0 20px;
  padding-bottom:12px;
  border-bottom:1px solid var(--cor-borda);
}

/* --- Sem fotos de perfil --- */
.avatar-image-container,
.comments .avatar-image-container,
.comments .avatar-image-container img,
.comments-content .avatar-image-container,
.comment-block .avatar-image-container,
#comments-block .avatar-image-container{ display:none !important; }

/* Sem avatar, o Blogger deixa a indentacao antiga; anulamos. */
.comments .comment-block,
.comments .comments-content .comment-replies,
.comments .comments-content .comment-thread{ margin-left:0; }
.comments .comments-content .comment-content{ margin-left:0; }

/* --- Cartao de cada comentario --- */
.comments .comments-content .comment{
  margin:0 0 14px;
  padding:0;
  border:0;
  background:transparent;
  list-style:none;
}
.comments .comments-content .comment .comment-block,
#comments-block .comment-body{
  padding:18px 20px;
  background:var(--cor-superficie);
  border:1px solid var(--cor-borda);
  border-radius:3px;
}

/* Respostas: recuadas e com uma marca a esquerda. */
.comments .comments-content .comment-replies{
  margin-left:22px;
  padding-left:16px;
  border-left:2px solid var(--cor-borda);
}

.comment-content{ margin:8px 0 0; font-size:var(--texto-sm); color:var(--cor-texto); }
.comments .comments-content .user{
  margin:0;
  font-size:var(--texto-sm);
  font-weight:600;
  font-style:normal;
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  color:var(--cor-titulo);
}
.comments-content .datetime{
  font-size:10px;
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  color:var(--cor-texto-suave);
}
.comments-content .datetime a{ color:var(--cor-texto-suave); }

#comments-block .comment-author{
  margin:0 0 6px;
  font-size:var(--texto-sm);
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  color:var(--cor-titulo);
}
#comments-block .comment-body{ margin:0 0 14px; }
#comments-block .comment-body p{ margin:0; }
#comments-block .comment-footer{
  margin:0 0 22px;
  padding:0 20px;
  font-size:var(--texto-xs);
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
}

.comments .comment .comment-actions a,
.comments .comment .continue a{
  display:inline-block;
  margin:12px 8px 0 0;
  padding:6px 12px;
  border:1px solid var(--cor-borda);
  font-size:10px;
  text-transform:uppercase;
  letter-spacing:var(--espaco-letra);
  color:var(--cor-texto-suave);
  cursor:pointer;
  transition:background var(--transicao), color var(--transicao);
}
.comments .comment .comment-actions a:hover,
.comments .comment .continue a:hover{
  background:var(--cor-titulo);
  color:var(--cor-contraste);
}

.deleted-comment{ font-style:italic; color:var(--cor-texto-suave); }
.comments .comments-replybox{ max-width:100%; }
.comments .comment-form{
  margin-top:26px;
  padding:18px 20px;
  background:var(--cor-superficie);
  border:1px solid var(--cor-borda);
  border-radius:3px;
}
.comments .comment-form h4{ border:0; padding:0; margin:0 0 8px; }

/* ------------------------------------------------------------------
   12. PAGINACAO
   Setas em texto (<- ->) no lugar das imagens externas antigas.
   ------------------------------------------------------------------ */
#blog-pager{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:16px;
  width:100%;
  padding:20px 0;
  border-top:1px solid var(--cor-borda);
}
#blog-pager a{ color:var(--cor-texto-suave); }
#blog-pager a:hover{ color:var(--cor-link-hover); }
#blog-pager-newer-link{ order:3; }
#blog-pager-older-link{ order:1; }
#home-link{ order:2; }
#blog-pager-newer-link a::after{ content:" \2192"; }   /* seta para a direita */
#blog-pager-older-link a::before{ content:"\2190 "; }  /* seta para a esquerda */
.feed-links{ display:none; }

/* ------------------------------------------------------------------
   13. RODAPE
   ------------------------------------------------------------------ */
.footer{
  width:100%;
  max-width:var(--largura-site);
  margin:0 auto;
  padding:0 20px;
  font-size:var(--texto-sm);
}
#creditos{ width:100%; border-top:1px solid var(--cor-borda); }
.creditos{
  display:flex;
  align-items:center;
  justify-content:center;
  flex-wrap:wrap;
  gap:14px;
  padding:22px 10px;
  font-size:10px;
  letter-spacing:var(--espaco-letra);
  text-transform:uppercase;
  color:var(--cor-texto-suave);
}

/* Botao de tema, agora aqui no rodape: um botao-pilula pequeno,
   e nao mais o item alto da barra do menu. */
#tema-toggle{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:5px 10px;
  background:transparent;
  border:1px solid var(--cor-borda);
  border-radius:20px;
  font-family:var(--fonte-base);
  font-size:10px;
  letter-spacing:inherit;
  text-transform:inherit;
  color:var(--cor-texto-suave);
  cursor:pointer;
  -webkit-appearance:none;
  appearance:none;
  transition:color var(--transicao), border-color var(--transicao);
}
#tema-toggle:hover{ color:var(--cor-titulo); border-color:var(--cor-texto-suave); }
#tema-toggle:focus-visible{
  outline:2px solid var(--cor-link-hover);
  outline-offset:2px;
}
#creditos .menu-icone{ width:14px; height:14px; }

/* ------------------------------------------------------------------
   14. RESPONSIVO
   Um unico ponto de quebra: abaixo de 900px tudo vira coluna unica.
   ------------------------------------------------------------------ */
@media screen and (max-width:900px){
  :root{ --titulo-blog:28px; --titulo-post:20px; --texto-base:14px; --gap:0px; }

  #outer-wrapper{ padding:0 16px; margin-bottom:50px; }

  #content-wrapper{ display:block; }
  #main-wrapper, #sidebar-wrapper{ width:100%; flex:none; }
  #sidebar-wrapper{ margin-top:50px; position:static; }

  .crosscol .PopularPosts ul li{ flex:0 0 49%; }
  .post{ margin-bottom:50px; }
  .post-footer{ justify-content:flex-start; }
  .post-footer-line-2{ text-align:left; }
}

@media screen and (max-width:600px){
  .crosscol .PopularPosts ul li{ flex:0 0 100%; }
  #at-gambar{ display:none; }
}

/* ------------------------------------------------------------------
   15. EDITOR LAYOUT DO BLOGGER
   A pagina de Layout usa <body id="layout"> e carrega este mesmo CSS.
   Estas regras existem so para que todas as seccoes fiquem visiveis e
   editaveis no painel. Nao afetam o blog publicado.
   ------------------------------------------------------------------ */
body#layout #content-wrapper{ display:flex; gap:20px; }
body#layout #main-wrapper{ max-width:none; margin:0; }
body#layout #content-wrapper.sem-sidebar #sidebar-wrapper{
  display:block !important;
  width:auto;
  flex:1;
}
body#layout #header-wrapper,
body#layout #crosscol-wrapper,
body#layout #menu-wrapper,
body#layout #footer-wrapper{ padding:0; }
body#layout #menu-wrapper{ position:static; }
body#layout .menu-topo{ display:block; }
body#layout .menu-links{ position:static; display:block; }
body#layout .menu-links .section,
body#layout .menu-links .widget,
body#layout .menu-links .widget-content,
body#layout .menu-links #PageList1 ul{ display:block; }
body#layout #home-wrapper{ display:block; }
body#layout .date-outer,
body#layout .date-posts{ display:block; }
body#layout #tema-toggle{ display:none; }
body#layout body{ padding-bottom:0; }

/* ------------------------------------------------------------------
   16. BOTAO DE TEMA
   O aspeto principal vem da seccao 13 (rodape), onde o botao agora
   vive. Esta regra so garante que navegadores nao aplicam a
   aparencia nativa de <button>.
   ------------------------------------------------------------------ */

/* Respeita quem pediu menos animacoes nas definicoes do sistema. */
@media (prefers-reduced-motion: reduce){
  *, *::before, *::after{
    transition-duration:.01ms !important;
    animation-duration:.01ms !important;
  }
}

