(function () {
  var ICONES = [
    { termos: ['home', 'inicio', 'principal'],
      svg: '<path d="M3 10.6 12 3.5l9 7.1"/><path d="M5.6 9.4V20h12.8V9.4"/><path d="M9.8 20v-5.4h4.4V20"/>' },
    { termos: ['sobre', 'about', 'quem', 'autor', 'perfil'],
      svg: '<circle cx="12" cy="8" r="3.4"/><path d="M4.8 20c0-3.6 3.2-5.6 7.2-5.6s7.2 2 7.2 5.6"/>' },
    { termos: ['blog', 'post', 'artigo', 'texto', 'escrit'],
      svg: '<path d="M5 4h14v16H5z"/><path d="M8.5 8.5h7M8.5 12h7M8.5 15.5h4"/>' },
    { termos: ['arquivo', 'historico', 'log'],
      svg: '<path d="M3.5 7h17v3h-17z"/><path d="M5 10v10h14V10"/><path d="M10 14h4"/>' },
    { termos: ['marcador', 'tag', 'categoria', 'label'],
      svg: '<path d="M3.5 12.5 12 4h7.5v7.5L11 20z"/><circle cx="16" cy="8" r="1.3"/>' },
    { termos: ['foto', 'imagem', 'galeria', 'photo'],
      svg: '<path d="M3.5 5.5h17v13h-17z"/><circle cx="8.5" cy="10" r="1.6"/><path d="m4 16 5-4.5 4.5 4 3-2.5 4 3.5"/>' },
    { termos: ['mapa', 'map', 'viagem', 'lugar'],
      svg: '<path d="m3.5 6.5 5.5-2 6 2 5.5-2v13l-5.5 2-6-2-5.5 2z"/><path d="M9 4.5v13M15 6.5v13"/>' },
    { termos: ['contato', 'contacto', 'email', 'fala', 'mensagem'],
      svg: '<path d="M3.5 6h17v12h-17z"/><path d="m3.5 7 8.5 6 8.5-6"/>' },
    { termos: ['link', 'projeto', 'stuff', 'coisa'],
      svg: '<path d="M10 13.5a4 4 0 0 0 5.7 0l2.6-2.6a4 4 0 0 0-5.7-5.7l-1.3 1.3"/><path d="M14 10.5a4 4 0 0 0-5.7 0l-2.6 2.6a4 4 0 0 0 5.7 5.7l1.3-1.3"/>' },
    { termos: ['livro', 'leitura', 'book', 'biblioteca'],
      svg: '<path d="M4.5 4.5h11a2.5 2.5 0 0 1 2.5 2.5v13H7a2.5 2.5 0 0 1-2.5-2.5z"/><path d="M18 20h1.5V4.5H18"/>' },
    { termos: ['busca', 'pesquis', 'search'],
      svg: '<circle cx="10.5" cy="10.5" r="6"/><path d="m15 15 4.5 4.5"/>' },
    { termos: ['rss', 'feed', 'assinar'],
      svg: '<path d="M5 12a7 7 0 0 1 7 7"/><path d="M5 6.5A12.5 12.5 0 0 1 17.5 19"/><circle cx="5.8" cy="18.2" r="1.4"/>' }
  ];

  // Usado quando o nome da pagina nao corresponde a nenhum termo.
  var ICONE_PADRAO = '<circle cx="12" cy="12" r="7.5"/><circle cx="12" cy="12" r="2.2"/>';

  function semAcentos(t) {
    return t.toLowerCase()
            .normalize ? t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
                       : t.toLowerCase();
  }

  function escolher(texto) {
    var t = semAcentos(texto);
    for (var i = 0; i < ICONES.length; i++) {
      for (var j = 0; j < ICONES[i].termos.length; j++) {
        if (t.indexOf(ICONES[i].termos[j]) > -1) return ICONES[i].svg;
      }
    }
    return ICONE_PADRAO;
  }

  function montar(desenho) {
    var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'menu-icone');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('aria-hidden', 'true');
    svg.innerHTML = desenho;
    return svg;
  }

  // O icone do botao de tema nao e tratado aqui: muda conforme o
  // tema escolhido, por isso vive no script TEMA: TROCA.
  var links = document.querySelectorAll('#PageList1 li a');
  for (var i = 0; i < links.length; i++) {
    var a = links[i];
    if (a.querySelector('.menu-icone')) continue;   // ja tratado

    var rotulo = document.createElement('span');
    rotulo.className = 'menu-rotulo';
    rotulo.textContent = a.textContent.trim();

    a.textContent = '';
    a.appendChild(montar(escolher(rotulo.textContent)));
    a.appendChild(rotulo);
  }
})();
//

