(function () {
  document.querySelectorAll('.post-location-fallback').forEach(function (a) {
    var texto = a.querySelector('.post-location-texto');
    var pai = a.closest('.post-location-inner');
    if (!texto || !pai) return;

    var iso = pai.getAttribute('data-desde') || '';
    var ano = iso ? parseInt(iso.slice(0, 4), 10) : NaN;

    texto.textContent = (!isNaN(ano) && ano < 2021)
      ? 'Brasília, Brasil'
      : 'Porto, Portugal';
  });
})();
