(function () {
  /* Cada tema tem nome e desenho proprios. O "icone" e o conteudo
     de um <svg viewBox="0 0 24 24">, sem a etiqueta exterior. */
  var TEMAS = [
    { id: 'claro', nome: '',
      icone: '<circle cx="12" cy="12" r="4.2"/><path d="M12 2.6v2.4M12 19v2.4M21.4 12H19M5 12H2.6M18.6 5.4 16.9 7.1M7.1 16.9l-1.7 1.7M18.6 18.6 16.9 16.9M7.1 7.1 5.4 5.4"/>' },
    { id: 'escuro', nome: '',
      icone: '<path d="M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5z"/>' },
    { id: 'sepia', nome: '',
      icone: '<path d="M4.5 8h12v6a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4z"/><path d="M16.5 9.5h1.8a2.2 2.2 0 0 1 0 4.4h-1.8"/><path d="M7.5 3.5v2M10.5 3.5v2M13.5 3.5v2"/>' },
    { id: 'terminal', nome: '',
      icone: '<rect x="2.8" y="4.5" width="18.4" height="15" rx="2"/><path d="m7 9.5 3 2.5-3 2.5"/><path d="M12.5 15h4.5"/>' },
    { id: 'riso', nome: '',
      icone: '<circle cx="9.4" cy="12" r="5.6"/><circle cx="14.6" cy="12" r="5.6"/>' },
    { id: 'azulejo', nome: '',
      icone: '<rect x="6.5" y="6.5" width="11" height="11" transform="rotate(45 12 12)"/><circle cx="12" cy="12" r="2.4"/>' }
  ];

  var raiz = document.documentElement;
  var btn  = document.getElementById('tema-toggle');
  var alvo = document.getElementById('tema-nome');
  if (!btn || !alvo) return;

  /* O <svg> e criado uma vez; depois so se troca o desenho la
     dentro, a cada mudanca de tema. */
  var svg = btn.querySelector('.menu-icone');
  if (!svg) {
    svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'menu-icone');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('aria-hidden', 'true');
    var ponto = btn.querySelector('.tema-ponto');
    if (ponto) btn.replaceChild(svg, ponto);
    else btn.insertBefore(svg, btn.firstChild);
  }

  // Sem escolha guardada, mostra o tema que o sistema esta a aplicar.
  function atual() {
    var t = raiz.getAttribute('data-tema');
    if (t) return t;
    return (window.matchMedia &&
            window.matchMedia('(prefers-color-scheme: dark)').matches)
      ? 'escuro' : 'claro';
  }

  function indice(id) {
    for (var i = 0; i < TEMAS.length; i++) {
      if (TEMAS[i].id === id) return i;
    }
    return 0;
  }

  function pintar() {
    var i = indice(atual());
    svg.innerHTML = TEMAS[i].icone;
    alvo.textContent = TEMAS[i].nome;
    btn.title = 'Tema atual: ' + TEMAS[i].nome +
                '. Clique para ' + TEMAS[(i + 1) % TEMAS.length].nome + '.';
  }

  btn.addEventListener('click', function () {
    var novo = TEMAS[(indice(atual()) + 1) % TEMAS.length].id;
    raiz.setAttribute('data-tema', novo);
    try { localStorage.setItem('tema', novo); } catch (e) {}
    pintar();
  });

  // Se o leitor nunca escolheu, acompanha as mudancas do sistema.
  if (window.matchMedia) {
    var mq = window.matchMedia('(prefers-color-scheme: dark)');
    var aoMudar = function () { if (!raiz.getAttribute('data-tema')) pintar(); };
    if (mq.addEventListener) mq.addEventListener('change', aoMudar);
    else if (mq.addListener) mq.addListener(aoMudar);
  }

  pintar();
})();
